<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
			<view class="top" :style="{'backgroundImage':`url(${baseUrl}/uni/jf-shop-bg.png)`}">
				<view class="tit">我的余额(元)</view>
				<view class="money">{{user.balance}}</view>
				<view class="bot">
					<view class="btn" @click="toNext('/pages/my/sy-list')">收益明细</view>
					<view class="center"></view>
					<view class="btn" @click="toNext(`/pages/my/recharge`)">余额充值</view>
					<view class="center"></view>
					<view class="btn" @click="toNext(`/pages/my/my-wallet`)">申请提现</view>
				</view>
			</view>
			<view class="user-scroll">
				<block v-if="lists.length>0">
					<view style="height: 20rpx;"></view>
					<view class="user-items">
						<view class="user-item" v-for="(item,index) in lists" :key="index">
							<image :src="item.head_pic" mode="aspectFill" class="user-img" />
							<view class="right">
								<view class="nickname">{{item.nickname}}</view>
								<view class="phone">{{item.mobile}}</view>
							</view>
						</view>
					</view>
					<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
				</block>
				<view class="empty-view" v-else>
					<view class="empty-container">
						<u-empty text="暂无相关数据" :icon="emptyIcon" />
					</view>
				</view>
			</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				cate_list: [{
					'id': 0,
					'name': '全部'
				}],
				form: {
					pageIndex: 1,
					pageSize: 20,
				}
			}
		},
		onLoad(e) {
			_this = this;
			_this.get_user_info()
			_this.get_ywy_list()
		},
		onReachBottom() {
			if (_this.hasMore) {
				_this.form.pageIndex++
				_this.get_ywy_list()
			}
		},
		methods: {
			//获取用户信息
			async get_user_info() {
				const data = await _this.$post('port/user_info')
				if (data.code == 200) {
					this.user = data.result.user
				} else {
					this.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			async get_ywy_list() {
				const data = await _this.$post('port/ywy_list', _this.form)
				if (data.code == 200) {
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.form.pageSize
				} else {
					_this.hasMore = false
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	.container {
		.top {
			position: relative;
			height: 260rpx;
			background: left top/100% 100% no-repeat;
			color: #fff;
			@include flex-box(column, space-evenly, center);

			.tit {
				font-size: 26rpx;
				align-self: flex-start;
				margin-left: 30rpx;
			}

			.money {
				font-size: 60rpx;
				font-weight: 500;
			}

			.bot {
				@include flex-box(null, null, center);

				.btn {
					width: 160rpx;
					height: 50rpx;
					border: 2rpx solid #fff;
					border-radius: 40rpx;
					text-align: center;
					box-sizing: border-box;
					line-height: 50rpx;
				}

				.center {
					width: 2rpx;
					height: 47rpx;
					background: #fff;
					margin: 0 30rpx;
				}
			}
		}
		.user-items{
			padding: 0 30rpx;
			.user-item{
				@include flex-box(row,null,center);
				background: #fff;
				border-radius: $border-radius;
				margin-bottom: 20rpx;
				padding: 0 20rpx;
				height: 140rpx;
				.user-img{
					width: 80rpx;
					height: 80rpx;
					border-radius: 50%;
					margin-right: 10rpx;
				}
				.right{
					.nickname{
						font-size: 30rpx;
						font-weight: 600;
					}
					.phone{
						margin-top: 10rpx;
					}
				}
			}
		}
		.empty-view {
			padding-top: 200rpx;
		}
	}
</style>